use xiom.io;

use xiom.string;
type Person = {
  name: Str;
  age: Int;
}

fn group_by_age(people: &Vec[Person]) -> Map[Int, Vec[Str]] {
  let groups: Map[Int, Vec[Str]] = Map[Int, Vec[Str]].new();
  let i = 0;
  while i < people.len() {
    let p = match people.get(i) { Some(v) => v, None => { i = i + 1; continue; } };
    let existing = match groups.get(&p.age) { Some(g) => g, None => {
      let empty: Vec[Str] = Vec[Str].new();
      empty
    }};
    let updated: Vec[Str] = Vec[Str].new();
    let j = 0;
    while j < existing.len() {
      let name = match existing.get(j) { Some(n) => n, None => "" };
      updated.push(name);
      j = j + 1;
    }
    updated.push(p.name);
    groups.insert(p.age, updated);
    i = i + 1;
  }
  return groups;
}

fn main() -> Int {
  let people: Vec[Person] = Vec[Person].new();
  people.push(Person{ name: "Alice", age: 25 });
  people.push(Person{ name: "Bob", age: 30 });
  people.push(Person{ name: "Carol", age: 25 });

  let groups = group_by_age(&people);
  let age_25 = match groups.get(&25) { Some(g) => g, None => Vec[Str].new() };
  io.println(to_string(age_25.len()));
  return 0;
}
